$root='<WINDOWS_FIXTURE>';$ErrorActionPreference='Stop';$processes=@(Get-CimInstance Win32_Process -ErrorAction Stop);if($processes.Count -lt 10){throw 'process inventory unavailable'};$owned=@($processes|Where-Object {$_.ExecutablePath -and $_.ExecutablePath.StartsWith($root+'\',[StringComparison]::OrdinalIgnoreCase)});$record=[ordered]@{recorded_utc=[DateTime]::UtcNow.ToString('o');reason='User stop instruction: R9 localhost fixture ownership gap; no runtime authorization remains';run_start_exists=(Test-Path (Join-Path $root 'run-start.json'));run_result_exists=(Test-Path (Join-Path $root 'run-result.json'));owned_executables=@($owned|Select-Object Name,ProcessId,ExecutablePath,CreationDate,SessionId);successful_process_inventory_count=$processes.Count;build_start_exists=(Test-Path (Join-Path $root 'build-start.json'));build_result_exists=(Test-Path (Join-Path $root 'build-result.json'));build_progress_exists=(Test-Path (Join-Path $root 'build-progress.json'));immutable_manifest_exists=(Test-Path (Join-Path $root 'immutable-inputs-before.json'));runtime_files=@(Get-ChildItem (Join-Path $root 'runtime') -Recurse -Force|Select-Object -ExpandProperty Name);probe_stopped=$false;probe_never_started=($owned.Count -eq 0 -and -not (Test-Path (Join-Path $root 'run-start.json')))};$record|ConvertTo-Json -Depth 8|Set-Content (Join-Path $root 'r9-runtime-stop.json');$record|Select-Object recorded_utc,run_start_exists,run_result_exists,successful_process_inventory_count,build_start_exists,build_result_exists,build_progress_exists,immutable_manifest_exists,probe_stopped,probe_never_started|ConvertTo-Json